class Solution {
public:
    int deleteString(std::string s) {
        int n = s.size();
        bool allSame = true;
        for (int i = 1; i < n; i++) {
            if (s[i] != s[0]) { allSame = false; break; }
        }
        if (allSame) return n;

        std::vector<std::vector<int>> lcp(n + 1, std::vector<int>(n + 1, 0));
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (s[i] == s[j]) lcp[i][j] = 1 + lcp[i + 1][j + 1];
            }
        }

        std::vector<int> dp(n, 1);
        for (int i = n - 1; i >= 0; i--) {
            for (int L = 1; L <= (n - i) / 2; L++) {
                if (lcp[i][i + L] >= L) {
                    dp[i] = std::max(dp[i], 1 + dp[i + L]);
                }
            }
        }
        return dp[0];
    }
};

class Solution {
    public int deleteString(String s) {
        int n = s.length();
        boolean allSame = true;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) != s.charAt(0)) { allSame = false; break; }
        }
        if (allSame) return n;

        int[][] lcp = new int[n + 1][n + 1];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (s.charAt(i) == s.charAt(j)) lcp[i][j] = 1 + lcp[i + 1][j + 1];
            }
        }

        int[] dp = new int[n];
        java.util.Arrays.fill(dp, 1);
        for (int i = n - 1; i >= 0; i--) {
            for (int L = 1; L <= (n - i) / 2; L++) {
                if (lcp[i][i + L] >= L) {
                    dp[i] = Math.max(dp[i], 1 + dp[i + L]);
                }
            }
        }
        return dp[0];
    }
}

var deleteString = function(s) {
    const n = s.length;
    let allSame = true;
    for (let i = 1; i < n; i++) {
        if (s[i] !== s[0]) { allSame = false; break; }
    }
    if (allSame) return n;

    const lcp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));
    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j >= 0; j--) {
            if (s[i] === s[j]) lcp[i][j] = 1 + lcp[i + 1][j + 1];
        }
    }

    const dp = new Array(n).fill(1);
    for (let i = n - 1; i >= 0; i--) {
        for (let L = 1; L <= Math.floor((n - i) / 2); L++) {
            if (lcp[i][i + L] >= L) {
                if (1 + dp[i + L] > dp[i]) dp[i] = 1 + dp[i + L];
            }
        }
    }
    return dp[0];
};
